//! Python-engine migration reader (mandate 4.1: the Python engine is
//! the migration source).
//!
//! Reads the `events` table the Python engine writes into the same
//! SQLite file and verifies its hash chain with the exact Python
//! algorithm: `sha256(prev_hash + "\n" + canonical_json([run_id,
//! seq, ts, schema_version, type, payload]))`, genesis prev_hash =
//! 64 zeros, canonical JSON = compact separators + sorted keys +
//! non-ASCII kept literal. Verified against a fixture generated by
//! the real Python engine (tests/fixtures).

use crate::storage::CoreStore;
use rusqlite::OptionalExtension;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct LegacyEvent {
    pub event_id: String,
    pub run_id: String,
    pub seq: i64,
    pub ts: String,
    pub schema_version: i64,
    #[serde(rename = "type")]
    pub kind: String,
    pub payload: serde_json::Value,
    pub prev_hash: String,
    pub hash: String,
}

#[derive(Debug)]
pub enum MigrationError {
    Storage(rusqlite::Error),
    ChainBroken { seq: i64, expected: String, found: String },
    NotSequential { expected_seq: i64, found_seq: i64 },
}

impl std::fmt::Display for MigrationError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>)
           -> std::fmt::Result {
        match self {
            Self::Storage(e) => write!(f, "storage error: {e}"),
            Self::ChainBroken { seq, expected, found } => write!(
                f, "hash chain broken at seq {seq}: expected \
                    {expected}, found {found}"),
            Self::NotSequential { expected_seq, found_seq } => write!(
                f, "event sequence broken: expected {expected_seq}, \
                    found {found_seq}"),
        }
    }
}

/// Which runs exist in the legacy event log (run_id, events, last
/// event type) - the migration overview.
pub fn legacy_runs(store: &CoreStore)
                   -> Result<Vec<(String, i64, String)>,
                              MigrationError> {
    if !legacy_table_exists(store)? {
        return Ok(Vec::new());   // fresh data dir, nothing to migrate
    }
    let conn = store.raw_conn();
    let mut stmt = conn.prepare(
        "SELECT run_id, COUNT(*), MAX(type) FROM events \
         GROUP BY run_id ORDER BY MIN(seq)").map_err(
             MigrationError::Storage)?;
    let rows = stmt.query_map([], |r| {
        Ok((r.get(0)?, r.get(1)?, r.get(2)?))
    }).map_err(MigrationError::Storage)?
      .collect::<Result<Vec<_>, _>>().map_err(
        MigrationError::Storage)?;
    Ok(rows)
}

/// All events of one legacy run, ordered by seq, chain VERIFIED.
/// A run that fails verification is refused - migration never
/// proceeds over a broken audit trail.
pub fn legacy_events(store: &CoreStore, run_id: &str)
                     -> Result<Vec<LegacyEvent>, MigrationError> {
    if !legacy_table_exists(store)? {
        return Ok(Vec::new());   // fresh data dir, nothing to migrate
    }
    let conn = store.raw_conn();
    let mut stmt = conn.prepare(
        "SELECT event_id, run_id, seq, ts, schema_version, type, \
         payload, prev_hash, hash FROM events WHERE run_id=? \
         ORDER BY seq").map_err(MigrationError::Storage)?;
    let rows = stmt.query_map(rusqlite::params![run_id], |r| {
        Ok(LegacyEvent {
            event_id: r.get(0)?,
            run_id: r.get(1)?,
            seq: r.get(2)?,
            ts: r.get(3)?,
            schema_version: r.get(4)?,
            kind: r.get(5)?,
            payload: serde_json::from_str::<serde_json::Value>(
                &r.get::<_, String>(6)?)
                .unwrap_or(serde_json::Value::Null),
            prev_hash: r.get(7)?,
            hash: r.get(8)?,
        })
    }).map_err(MigrationError::Storage)?
      .collect::<Result<Vec<_>, _>>().map_err(
        MigrationError::Storage)?;
    verify_chain(&rows)?;
    Ok(rows)
}

fn legacy_table_exists(store: &CoreStore) -> Result<bool,
                                                    MigrationError> {
    let conn = store.raw_conn();
    let found = conn.query_row(
        "SELECT 1 FROM sqlite_master WHERE type='table'          AND name='events'", [],
        |_| Ok(())).optional().map_err(MigrationError::Storage)?;
    Ok(found.is_some())
}

/// Verify the whole chain: linking (prev_hash), sequencing (seq) and
/// every event's hash recomputed with the Python algorithm.
pub fn verify_chain(events: &[LegacyEvent])
                    -> Result<(), MigrationError> {
    let mut prev = "0".repeat(64);
    for (i, e) in events.iter().enumerate() {
        let expected_seq = (i + 1) as i64;
        if e.seq != expected_seq {
            return Err(MigrationError::NotSequential {
                expected_seq, found_seq: e.seq });
        }
        if e.prev_hash != prev {
            return Err(MigrationError::ChainBroken {
                seq: e.seq,
                expected: prev.clone(),
                found: e.prev_hash.clone() });
        }
        let computed = event_hash(&e.prev_hash, &e.run_id, e.seq,
                                  &e.ts, e.schema_version, &e.kind,
                                  &e.payload);
        if computed != e.hash {
            return Err(MigrationError::ChainBroken {
                seq: e.seq, expected: computed,
                found: e.hash.clone() });
        }
        prev = e.hash.clone();
    }
    Ok(())
}

/// The exact Python `Store.append` hash (storage/__init__.py:162).
pub fn event_hash(prev_hash: &str, run_id: &str, seq: i64, ts: &str,
                  schema_version: i64, kind: &str,
                  payload: &serde_json::Value) -> String {
    let canonical = serde_json::to_string(&serde_json::json!([
        run_id, seq, ts, schema_version, kind, payload
    ])).unwrap_or_default();
    let mut hasher = Sha256::new();
    hasher.update(prev_hash.as_bytes());
    hasher.update(b"\n");
    hasher.update(canonical.as_bytes());
    hex(&hasher.finalize())
}

fn hex(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        out.push_str(&format!("{b:02x}"));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The fixture is COMMITTED (tests/fixtures/python_run.db):
    /// a run database produced by the real Python reference engine
    /// (las/), so the Rust reader is verified against genuine
    /// data, not a re-implementation of itself.  Regenerate by
    /// running any plan with the Python engine and copying the
    /// resulting runs database over it.
    /// Open a private copy: CoreStore adds agent-domain tables on
    /// open, and the committed fixture must stay pristine.
    fn fixture_copy(tag: &str) -> String {
        let src = concat!(env!("CARGO_MANIFEST_DIR"),
                          "/tests/fixtures/python_run.db");
        let dst = std::env::temp_dir().join(format!(
            "las-fixture-{tag}-{}.db", std::process::id()));
        std::fs::copy(src, &dst).expect("fixture exists");
        dst.to_string_lossy().into_owned()
    }

    #[test]
    fn reads_and_verifies_python_engine_fixture() {
        let path = fixture_copy("main");
        let store = CoreStore::open(path).unwrap();
        let runs = legacy_runs(&store).unwrap();
        assert!(!runs.is_empty(), "fixture has runs");
        let (run_id, events, last_type) = runs[0].clone();
        assert!(events > 0);
        assert!(!last_type.is_empty());
        let all = legacy_events(&store, &run_id).unwrap();
        assert_eq!(all.len() as i64, events);
        // The first event is run.created with a plan snapshot.
        assert_eq!(all[0].kind, "run.created");
        assert!(all[0].payload.get("plan").is_some(),
                "the plan snapshot survived migration reading");
    }

    #[test]
    fn tampered_payload_breaks_the_chain() {
        let path = fixture_copy("tamper");
        let store = CoreStore::open(path).unwrap();
        let runs = legacy_runs(&store).unwrap();
        let run_id = runs[0].0.clone();
        let mut events = legacy_events(&store, &run_id).unwrap();
        // Tamper with a payload without rehashing.
        if let Some(obj) = events[0].payload.as_object_mut() {
            obj.insert("evil".into(),
                       serde_json::Value::Bool(true));
        }
        assert!(verify_chain(&events).is_err(),
                "tampering is detected, never silently accepted");
    }

    #[test]
    fn missing_run_is_empty_not_error() {
        let store = CoreStore::in_memory().unwrap();
        let none = legacy_events(&store, "nope").unwrap();
        assert!(none.is_empty());
    }
}
